// ============================================================
// Main
// ============================================================
int main(int argc, char** argv) {
    bool fullscreen = false;
    std::string filename;
    bool help = false;
    bool version = false;
    bool keybinding = false;
    bool end_of_flags = false;

    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (!end_of_flags && arg == "--") {
            end_of_flags = true;
            continue;
        }
        if (!end_of_flags) {
            if (arg == "-h" || arg == "--help") { help = true; continue; }
            if (arg == "-v" || arg == "--version") { version = true; continue; }
            if (arg == "-f" || arg == "--fullscreen") { fullscreen = true; continue; }
            if (arg == "-k" || arg == "--key" || arg == "--keybinding") { keybinding = true; continue; }
            if (arg[0] == '-') { help = true; continue; }
        }
        filename = arg;
    }

    if (version) {
        std::cout << "1.4.1\n";
        return 0;
    }

    if (help) {
        print_help(argv[0]);
        // Print twice like original
        print_help(argv[0]);
        return 0;
    }

    if (keybinding) {
        print_keybindings();
        return 0;
    }

    // Read JSON
    std::string json_str;
    if (filename.empty()) {
        // Read from stdin
        // Show message to tty
        if (isatty(STDIN_FILENO)) {
            std::cerr << "Reading from stdin..." << std::endl;
        }
        // Actually the message goes to tty, not stderr
        // Write "Reading from stdin... " to /dev/tty
        int tty_fd = open("/dev/tty", O_WRONLY);
        if (tty_fd >= 0) {
            const char* msg = "Reading from stdin... ";
            write(tty_fd, msg, strlen(msg));
            close(tty_fd);
        }

        std::string line;
        while (std::getline(std::cin, line)) {
            json_str += line + "\n";
        }
    } else {
        std::ifstream f(filename);
        if (!f) {
            std::cerr << "Cannot open file: " << filename << "\n";
            return 1;
        }
        std::ostringstream ss;
        ss << f.rdbuf();
        json_str = ss.str();
    }

    // Parse JSON
    JsonPtr json = JsonParser::parse(json_str);

    // Initialize terminal
    get_term_size();

    // Run TUI
    App app(json, fullscreen);

    enable_raw_mode();

    // Startup sequence
    startup_sequence(fullscreen);

    // Run main loop
    run(app);

    // Final cleanup
    // Position sequence
    std::ostringstream pos;
    if (g_prev_lines > 1) {
        pos << "\x1b[" << (g_prev_lines - 1) << "B";
    }
    if (g_prev_width > 0) {
        pos << "\x1b[" << g_prev_width << "C";
    }
    pos << "\r";
    for (int i = 0; i < g_prev_lines - 1; i++) {
        pos << "\x1b[1A";
    }
    pos << "\x1b[6n";
    write_all(STDOUT_FILENO, pos.str());

    // Final frame
    std::string frame_output;
    int frame_lines, frame_width;
    render_frame(app, frame_output, frame_lines, frame_width);
    write_all(STDOUT_FILENO, frame_output);

    // Back to top
    std::ostringstream back;
    if (frame_lines > 1) {
        back << "\x1b[" << (frame_lines - 1) << "A";
    }
