// json-tui reimplementation
// A JSON terminal UI with interactive tree navigation

#include <algorithm>
#include <cassert>
#include <cstring>
#include <fcntl.h>
#include <iostream>
#include <memory>
#include <signal.h>
#include <sstream>
#include <string>
#include <sys/ioctl.h>
#include <termios.h>
#include <unistd.h>
#include <vector>
#include <fstream>
#include <map>

// ============================================================
// ANSI Color codes
// ============================================================
#define RESET       "\x1b[0m"
#define BOLD        "\x1b[1m"
#define BOLD_OFF    "\x1b[22m"
#define REVERSE     "\x1b[7m"
#define REVERSE_OFF "\x1b[27m"
#define FG_DEFAULT  "\x1b[39m"
#define BG_DEFAULT  "\x1b[49m"
#define FG_DARK_GRAY "\x1b[90m"
#define FG_RED      "\x1b[91m"
#define FG_GREEN    "\x1b[92m"
#define FG_YELLOW   "\x1b[93m"
#define FG_BLUE     "\x1b[94m"
#define FG_CYAN     "\x1b[96m"
#define FG_TEAL     "\x1b[36m"

// ============================================================
// JSON types
// ============================================================
enum class JsonType {
    Null,
    Bool,
    Number,
    String,
    Array,
    Object
};

struct JsonValue;
using JsonPtr = std::shared_ptr<JsonValue>;
using JsonArray = std::vector<JsonPtr>;
using JsonObject = std::vector<std::pair<std::string, JsonPtr>>;

struct JsonValue {
    JsonType type;
    bool bool_val = false;
    double num_val = 0.0;
    std::string str_val;
    JsonArray arr_val;
    JsonObject obj_val;

    static JsonPtr make_null() {
        auto v = std::make_shared<JsonValue>();
        v->type = JsonType::Null;
        return v;
    }
    static JsonPtr make_bool(bool b) {
        auto v = std::make_shared<JsonValue>();
        v->type = JsonType::Bool;
        v->bool_val = b;
        return v;
    }
    static JsonPtr make_number(double n) {
        auto v = std::make_shared<JsonValue>();
        v->type = JsonType::Number;
        v->num_val = n;
        return v;
    }
    static JsonPtr make_string(std::string s) {
        auto v = std::make_shared<JsonValue>();
        v->type = JsonType::String;
        v->str_val = std::move(s);
        return v;
    }
    static JsonPtr make_array() {
        auto v = std::make_shared<JsonValue>();
        v->type = JsonType::Array;
        return v;
    }
    static JsonPtr make_object() {
        auto v = std::make_shared<JsonValue>();
        v->type = JsonType::Object;
        return v;
    }
};

// ============================================================
// JSON Parser
// ============================================================
class JsonParser {
public:
    std::string input;
    size_t pos = 0;

    explicit JsonParser(std::string s) : input(std::move(s)) {}

    void skip_ws() {
        while (pos < input.size() && (input[pos] == ' ' || input[pos] == '\t' || 
               input[pos] == '\n' || input[pos] == '\r'))
            pos++;
    }

    char peek() { return pos < input.size() ? input[pos] : 0; }
    char consume() { return pos < input.size() ? input[pos++] : 0; }

    bool expect(char c) {
        skip_ws();
        if (peek() == c) { consume(); return true; }
        return false;
    }

    std::string parse_string() {
        if (!expect('"')) return "";
        std::string result;
        while (pos < input.size() && input[pos] != '"') {
            if (input[pos] == '\\') {
                pos++;
                char esc = consume();
                switch (esc) {
                    case '"': result += '"'; break;
                    case '\\': result += '\\'; break;
                    case '/': result += '/'; break;
                    case 'b': result += '\b'; break;
                    case 'f': result += '\f'; break;
                    case 'n': result += '\n'; break;
                    case 'r': result += '\r'; break;
                    case 't': result += '\t'; break;
                    case 'u': {
                        // Parse 4 hex digits
                        std::string hex;
                        for (int i = 0; i < 4 && pos < input.size(); i++)
                            hex += consume();
                        unsigned int codepoint = 0;
                        try { codepoint = std::stoul(hex, nullptr, 16); } catch (...) {}
                        // Simple UTF-8 encoding
                        if (codepoint < 0x80) {
                            result += (char)codepoint;
                        } else if (codepoint < 0x800) {
                            result += (char)(0xC0 | (codepoint >> 6));
                            result += (char)(0x80 | (codepoint & 0x3F));
                        } else {
                            result += (char)(0xE0 | (codepoint >> 12));
                            result += (char)(0x80 | ((codepoint >> 6) & 0x3F));
                            result += (char)(0x80 | (codepoint & 0x3F));
                        }
                        break;
                    }
                    default: result += esc; break;
                }
            } else {
                result += consume();
            }
        }
        expect('"');
        return result;
    }

    JsonPtr parse_value() {
        skip_ws();
        if (pos >= input.size()) return JsonValue::make_null();

        char c = peek();

        if (c == '"') {
            return JsonValue::make_string(parse_string());
        } else if (c == '{') {
            return parse_object();
        } else if (c == '[') {
            return parse_array();
        } else if (c == 't') {
            pos += 4; // "true"
            return JsonValue::make_bool(true);
        } else if (c == 'f') {
            pos += 5; // "false"
            return JsonValue::make_bool(false);
        } else if (c == 'n') {
            pos += 4; // "null"
            return JsonValue::make_null();
        } else if (c == '-' || (c >= '0' && c <= '9')) {
            return parse_number();
        }

        return JsonValue::make_null();
    }

    JsonPtr parse_number() {
        std::string s;
        if (peek() == '-') s += consume();
        while (pos < input.size() && input[pos] >= '0' && input[pos] <= '9')
            s += consume();
        if (pos < input.size() && input[pos] == '.') {
            s += consume();
            while (pos < input.size() && input[pos] >= '0' && input[pos] <= '9')
                s += consume();
        }
        if (pos < input.size() && (input[pos] == 'e' || input[pos] == 'E')) {
            s += consume();
            if (pos < input.size() && (input[pos] == '+' || input[pos] == '-'))
                s += consume();
            while (pos < input.size() && input[pos] >= '0' && input[pos] <= '9')
                s += consume();
        }
        double val = 0;
        try { val = std::stod(s); } catch (...) {}
        return JsonValue::make_number(val);
    }

    JsonPtr parse_object() {
        expect('{');
        auto obj = JsonValue::make_object();
        skip_ws();
        if (peek() == '}') { consume(); return obj; }

        while (pos < input.size()) {
            skip_ws();
            if (peek() != '"') break;
            std::string key = parse_string();
            skip_ws();
            expect(':');
            auto val = parse_value();
            obj->obj_val.push_back({key, val});
            skip_ws();
            if (peek() == ',') { consume(); continue; }
            if (peek() == '}') { consume(); break; }
            break;
        }
        // Sort object keys alphabetically
        std::sort(obj->obj_val.begin(), obj->obj_val.end(),
            [](const auto& a, const auto& b) { return a.first < b.first; });
        return obj;
    }

    JsonPtr parse_array() {
        expect('[');
        auto arr = JsonValue::make_array();
        skip_ws();
        if (peek() == ']') { consume(); return arr; }

        while (pos < input.size()) {
            arr->arr_val.push_back(parse_value());
            skip_ws();
            if (peek() == ',') { consume(); continue; }
            if (peek() == ']') { consume(); break; }
            break;
        }
        return arr;
    }

    static JsonPtr parse(const std::string& s) {
        JsonParser p(s);
        p.skip_ws();
        return p.parse_value();
    }
};

// ============================================================
// Format number for display
// ============================================================
std::string format_number(double val) {
    // Check if it's an integer
    if (val == (long long)val && val >= -1e15 && val <= 1e15) {
        return std::to_string((long long)val);
    }
    // Use default formatting
    std::ostringstream ss;
    ss << val;
    return ss.str();
}

// ============================================================
// Terminal size
// ============================================================
static int g_term_rows = 24;
static int g_term_cols = 80;

void get_term_size() {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        g_term_rows = ws.ws_row > 0 ? ws.ws_row : 24;
        g_term_cols = ws.ws_col > 0 ? ws.ws_col : 80;
    }
}

// ============================================================
// Terminal raw mode
// ============================================================
static struct termios orig_termios;
static bool raw_mode_active = false;

void enable_raw_mode() {
    if (!isatty(STDIN_FILENO)) return;
    tcgetattr(STDIN_FILENO, &orig_termios);
    struct termios raw = orig_termios;
    raw.c_iflag &= ~(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
    raw.c_oflag &= ~(OPOST);
    raw.c_cflag |= CS8;
    raw.c_lflag &= ~(ECHO | ICANON | IEXTEN | ISIG);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw);
    raw_mode_active = true;
}

void disable_raw_mode() {
    if (raw_mode_active) {
        tcsetattr(STDIN_FILENO, TCSAFLUSH, &orig_termios);
        raw_mode_active = false;
    }
}

// ============================================================
// Tree node structure
// ============================================================
struct TreeNode {
    JsonPtr value;
    std::string key; // "" for array elements
    int depth;
    bool expanded;
    bool is_last_in_parent; // for comma rendering
    std::vector<TreeNode> children;
    bool is_table_view; // array of objects with 2+ items

    TreeNode(JsonPtr val, std::string k, int d, bool last)
        : value(val), key(std::move(k)), depth(d), is_last_in_parent(last),
          expanded(false), is_table_view(false) {}
};

// ============================================================
// Build tree
// ============================================================
bool is_table_view_array(const JsonPtr& val) {
    if (val->type != JsonType::Array) return false;
    if (val->arr_val.size() < 2) return false;
    for (const auto& elem : val->arr_val) {
        if (elem->type != JsonType::Object) return false;
    }
    return true;
}

TreeNode build_tree(JsonPtr val, std::string key, int depth, bool is_last) {
    TreeNode node(val, std::move(key), depth, is_last);

    // Set initial expansion state
    if (depth == 0) {
        node.expanded = true;
    } else if (depth == 1 && val->type == JsonType::Object) {
        node.expanded = true;
    } else {
        node.expanded = false;
    }

    // Check table view
    node.is_table_view = is_table_view_array(val);

    // Build children
    if (val->type == JsonType::Object) {
        size_t n = val->obj_val.size();
        for (size_t i = 0; i < n; i++) {
            bool last = (i == n - 1);
            node.children.push_back(
                build_tree(val->obj_val[i].second, val->obj_val[i].first, depth + 1, last));
        }
    } else if (val->type == JsonType::Array) {
        size_t n = val->arr_val.size();
        for (size_t i = 0; i < n; i++) {
            bool last = (i == n - 1);
            node.children.push_back(
                build_tree(val->arr_val[i], "", depth + 1, last));
        }
    }

    return node;
}

// ============================================================
// Visible line structure
// ============================================================
struct VisibleLine {
    // What to render
    enum class LineType {
        Container,   // { or [ line (opening)
        ClosingBrace,// } or ]
        Scalar,      // leaf value
    };

    LineType type;
    TreeNode* node;       // the node
    bool is_closing;      // is this the closing brace line?
    int depth;            // indentation depth

    VisibleLine(LineType t, TreeNode* n, int d, bool closing = false)
        : type(t), node(n), depth(d), is_closing(closing) {}
};

// ============================================================
// Collect visible lines
// ============================================================
void collect_lines(TreeNode& node, std::vector<VisibleLine>& lines) {
    JsonType type = node.value->type;

    if (type == JsonType::Object || type == JsonType::Array) {
        // Opening line
        lines.push_back(VisibleLine(VisibleLine::LineType::Container, &node, node.depth, false));

        if (node.expanded) {
            // Children
            for (auto& child : node.children) {
                collect_lines(child, lines);
            }
            // Closing line
            lines.push_back(VisibleLine(VisibleLine::LineType::ClosingBrace, &node, node.depth, true));
        }
    } else {
        // Scalar
        lines.push_back(VisibleLine(VisibleLine::LineType::Scalar, &node, node.depth, false));
    }
}

// ============================================================
// Render a single cell (character with color)
// ============================================================
struct StyledText {
    std::string text;   // content without escapes
    std::string prefix; // escape codes before
    std::string suffix; // escape codes after

    StyledText() {}
    StyledText(std::string t, std::string pre = "", std::string suf = "")
        : text(std::move(t)), prefix(std::move(pre)), suffix(std::move(suf)) {}

    std::string render(bool selected) const {
        std::string result = prefix;
        if (selected) result += REVERSE;
        result += text;
        if (selected) result += REVERSE_OFF;
        result += suffix;
        return result;
    }

    size_t visible_len() const { return text.size(); }
};

// ============================================================
// Render a line to a string (with colors)
// ============================================================

// Get display string for a value (colored)
// Returns: display_text, raw_visible_text
struct LineContent {
    std::string output; // full ANSI-colored output (no newline)
    int visible_width;  // number of visible chars
};

std::string value_color(const JsonPtr& val) {
    switch (val->type) {
        case JsonType::Null:   return FG_RED;
        case JsonType::Bool:   return FG_YELLOW;
        case JsonType::Number: return FG_CYAN;
        case JsonType::String: return FG_GREEN;
        default: return "";
    }
}

std::string scalar_text(const JsonPtr& val) {
    switch (val->type) {
        case JsonType::Null:   return "null";
        case JsonType::Bool:   return val->bool_val ? "true" : "false";
        case JsonType::Number: return format_number(val->num_val);
        case JsonType::String: return "\"" + val->str_val + "\"";
        default: return "";
    }
}

// ============================================================
// Compute "prefix" for a key (indent + "key": )
// Returns: {prefix_with_escapes, visible_prefix_len}
// ============================================================
std::pair<std::string, int> make_key_prefix(const std::string& key, int depth) {
    std::string indent(depth * 2, ' ');
    if (key.empty()) {
        // array element - no key
        return {indent, (int)indent.size()};
    }
    std::string quoted_key = "\"" + key + "\"";
    std::string prefix = indent + FG_BLUE + quoted_key + FG_DEFAULT + ": ";
    int vis_len = (int)indent.size() + (int)quoted_key.size() + 2; // ": " = 2 chars
    return {prefix, vis_len};
}

// Word-wrap a string to fit in available_width
std::vector<std::string> word_wrap(const std::string& text, int available_width) {
    if (available_width <= 0) return {text};

    std::vector<std::string> result;

    // Split into words
    std::vector<std::string> words;
    std::string word;
    for (char c : text) {
        if (c == ' ') {
            if (!word.empty()) { words.push_back(word); word = ""; }
        } else {
            word += c;
        }
    }
    if (!word.empty()) words.push_back(word);

    if (words.empty()) { result.push_back(""); return result; }

    std::string line;
    for (const auto& w : words) {
        if (line.empty()) {
            line = w;
        } else if ((int)(line.size() + 1 + w.size()) <= available_width) {
            line += ' ' + w;
        } else {
            result.push_back(line);
            line = w;
        }
    }
    if (!line.empty()) result.push_back(line);

    return result;
}

// ============================================================
// Render lines to screen
// ============================================================
// A rendered "display line" (one row in terminal)
struct DisplayLine {
    std::string content; // ANSI colored content (no trailing newline)
    int visible_width;   // number of visible characters
};

// Render a VisibleLine to one or more display lines
// selected: true if this line is selected (should be highlighted)
// term_cols: terminal width for wrapping
std::vector<DisplayLine> render_visible_line(
    const VisibleLine& vl, bool selected, int term_cols)
{
    TreeNode* node = vl.node;
    JsonPtr val = node->value;
    int depth = vl.depth;
    std::string indent(depth * 2, ' ');

    std::vector<DisplayLine> result;

    if (vl.is_closing) {
        // Closing brace: } or ]
        char brace = (val->type == JsonType::Object) ? '}' : ']';
        std::string comma = node->is_last_in_parent ? "" : ",";
        std::string text = indent + brace + comma;
        std::string colored = indent;
        if (selected) colored += REVERSE;
        colored += brace;
        if (selected) colored += REVERSE_OFF;
        colored += FG_DEFAULT + BG_DEFAULT;
        colored += comma;
        DisplayLine dl;
        dl.visible_width = (int)text.size();
        dl.content = colored;
        result.push_back(dl);
        return result;
    }

    // Container or scalar opening
    auto [key_prefix, key_prefix_len] = make_key_prefix(node->key, depth);

    if (val->type == JsonType::Object || val->type == JsonType::Array) {
        // Container opening
        char open_brace = (val->type == JsonType::Object) ? '{' : '[';
        char close_brace = (val->type == JsonType::Object) ? '}' : ']';

        std::string comma = node->is_last_in_parent ? "" : ",";

        if (!node->expanded) {
            // Collapsed: {....} or [....]
            std::string collapsed_text = std::string(1, open_brace) + "..." + close_brace + comma;
            std::string colored = key_prefix;
            colored += BOLD;
            if (selected) colored += REVERSE;
            colored += collapsed_text;
            if (selected) colored += REVERSE_OFF;
            colored += RESET + FG_DEFAULT + BG_DEFAULT;

            int vis = key_prefix_len + (int)collapsed_text.size();
            DisplayLine dl;
            dl.visible_width = vis;
            dl.content = colored;
            result.push_back(dl);
        } else {
            // Expanded: { or [
            // Show table view hint if applicable
            std::string table_hint = "";
            if (node->is_table_view && !vl.is_closing) {
                table_hint = "   " + std::string(FG_DARK_GRAY) + "(table view)" + FG_DEFAULT;
            }

            std::string open_str(1, open_brace);
            std::string colored = key_prefix;
            colored += BOLD;
            if (selected) colored += REVERSE;
            colored += open_str;
            if (selected) colored += REVERSE_OFF;
            colored += RESET + FG_DEFAULT + BG_DEFAULT;
            colored += table_hint;

            int vis = key_prefix_len + 1; // just the open brace
            if (!table_hint.empty()) vis += 3 + 12; // "   (table view)" = 15 chars
            DisplayLine dl;
            dl.visible_width = vis;
            dl.content = colored;
            result.push_back(dl);
        }
    } else {
        // Scalar value
        std::string comma = node->is_last_in_parent ? "" : ",";
        std::string color = value_color(val);
        std::string text = scalar_text(val);

        // Available width for value
        int available = term_cols - key_prefix_len;
        std::string full_text = text + comma;

        if (available > 0 && (int)full_text.size() > available) {
            // Need to word-wrap
            // Wrap the full_text including the closing quote/comma
            auto lines = word_wrap(full_text, available);

            for (size_t i = 0; i < lines.size(); i++) {
                std::string line_content;
                if (i == 0) {
                    line_content = key_prefix;
                } else {
                    // Continuation line: indent to key_prefix_len
                    line_content = std::string(key_prefix_len, ' ');
                    // Apply key color to spaces? Let me check...
                    // Actually in the test: "  [94m     [39m  " suggests key-colored spaces
                    // But let me use simpler approach first
                    // Actually: the visible line is: indent + key_colored_spaces + ': '
                    // But for continuation, it's just spaces (no key)
                    // Wait from test: '  [94m"     "[39m  ' 
                    // Let me re-examine...
                    // From earlier: '  [94m     [39m  [92mwindow...'
                    // That's: 2 spaces + 5 colored spaces + 2 spaces + value
                    // The 5 colored spaces represent the key "key" (5 chars with quotes)
                    // The 2 trailing spaces represent ': '
                    // So: indent + key_quoted_colored_as_spaces + ': '
                    // Actually I think the key part IS colored but shown as spaces
                    // Let me implement this:
                    line_content = std::string(depth * 2, ' '); // indent (plain)
                    if (!node->key.empty()) {
                        std::string key_spaces(node->key.size() + 2, ' '); // key + quotes
                        line_content += FG_BLUE + key_spaces + FG_DEFAULT + "  "; // ': '
                    }
                }

                std::string colored = line_content;
                colored += color;
                if (selected && i == 0) colored += REVERSE;
                colored += lines[i];
                if (selected && i == 0) colored += REVERSE_OFF;
                colored += FG_DEFAULT + BG_DEFAULT;

                int vis;
                if (i == 0) {
                    vis = key_prefix_len + (int)lines[i].size();
                } else {
                    vis = key_prefix_len + (int)lines[i].size();
                }

                DisplayLine dl;
                dl.visible_width = vis;
                dl.content = colored;
                result.push_back(dl);
            }
        } else {
            // Single line
            std::string colored = key_prefix;
            colored += color + BG_DEFAULT;
            if (selected) colored += REVERSE;
            colored += full_text;
            if (selected) colored += REVERSE_OFF;
            colored += FG_DEFAULT + BG_DEFAULT;

            DisplayLine dl;
            dl.visible_width = key_prefix_len + (int)full_text.size();
            dl.content = colored;
            result.push_back(dl);
        }
    }

    return result;
}

// ============================================================
// Application state
// ============================================================
struct App {
    TreeNode root;
    std::vector<VisibleLine> visible_lines; // all visible lines
    int selected_idx = 0;    // selected visible line index
    int scroll_offset = 0;   // first visible line in viewport
    bool fullscreen;
    bool running = true;

    // For 'gg' detection
    bool last_key_was_g = false;

    // Display info
    int display_lines_count = 0; // how many lines were last displayed
    int display_frame_width = 0; // width of last frame

    App(JsonPtr json, bool fs) 
        : root(build_tree(json, "", 0, true)), fullscreen(fs) {
        root.is_last_in_parent = true;
        rebuild_visible();
    }

    void rebuild_visible() {
        visible_lines.clear();
        collect_lines(root, visible_lines);
        // Clamp selection
        if (selected_idx >= (int)visible_lines.size())
            selected_idx = (int)visible_lines.size() - 1;
        if (selected_idx < 0) selected_idx = 0;
    }

    void ensure_selected_visible(int term_rows) {
        int viewport_height = fullscreen ? term_rows : 
            std::min((int)visible_lines.size(), term_rows);

        if (viewport_height <= 0) viewport_height = 1;

        if (selected_idx < scroll_offset)
            scroll_offset = selected_idx;
        else if (selected_idx >= scroll_offset + viewport_height)
            scroll_offset = selected_idx - viewport_height + 1;

        // Clamp scroll offset
        if (scroll_offset < 0) scroll_offset = 0;
        int max_scroll = (int)visible_lines.size() - viewport_height;
        if (max_scroll < 0) max_scroll = 0;
        if (scroll_offset > max_scroll) scroll_offset = max_scroll;
    }

    void move_selection(int delta) {
        selected_idx += delta;
        if (selected_idx < 0) selected_idx = 0;
        if (selected_idx >= (int)visible_lines.size())
            selected_idx = (int)visible_lines.size() - 1;
    }

    void toggle_selected() {
        if (selected_idx < 0 || selected_idx >= (int)visible_lines.size()) return;
        VisibleLine& vl = visible_lines[selected_idx];
        if (vl.is_closing) return; // can't toggle closing brace
        TreeNode* node = vl.node;
        if (node->value->type != JsonType::Object && 
            node->value->type != JsonType::Array) return;

        node->expanded = !node->expanded;
        // If expanding, initialize child states
        if (node->expanded) {
            init_children_state(*node);
        }
        rebuild_visible();
    }

    void init_children_state(TreeNode& node) {
        // When expanding a node manually, children should be in collapsed state
        // (depth 2+ = all collapsed)
        // This is already handled by build_tree's initial state
        // But we need to make sure children of expanded nodes are properly initialized
        // Actually, the children already exist with their initial states
        // We don't need to reset them here
    }

    void deep_expand(TreeNode& node) {
        if (node.value->type == JsonType::Object || node.value->type == JsonType::Array) {
            node.expanded = true;
            for (auto& child : node.children)
                deep_expand(child);
        }
    }

    void deep_collapse(TreeNode& node) {
        if (node.value->type == JsonType::Object || node.value->type == JsonType::Array) {
            node.expanded = false;
            for (auto& child : node.children)
                deep_collapse(child);
        }
    }

    void expand_selected() {
        if (selected_idx < 0 || selected_idx >= (int)visible_lines.size()) return;
        VisibleLine& vl = visible_lines[selected_idx];
        if (vl.is_closing) return;
        TreeNode* node = vl.node;
        deep_expand(*node);
        rebuild_visible();
    }

    void collapse_selected() {
        if (selected_idx < 0 || selected_idx >= (int)visible_lines.size()) return;
        VisibleLine& vl = visible_lines[selected_idx];
        if (vl.is_closing) return;
        TreeNode* node = vl.node;
        deep_collapse(*node);
        rebuild_visible();
    }
};

// ============================================================
// Render frame
// ============================================================
void render_frame(App& app, std::string& output, int& frame_lines, int& frame_width) {
    get_term_size();
    int term_rows = g_term_rows;
    int term_cols = g_term_cols;

    app.ensure_selected_visible(term_rows);

    // Determine viewport
    int total_visible = (int)app.visible_lines.size();
    int viewport_height;
    if (app.fullscreen) {
        viewport_height = term_rows;
    } else {
        viewport_height = std::min(total_visible, term_rows);
    }

    int start = app.scroll_offset;
    int end = std::min(start + viewport_height, total_visible);

    // Render each visible line to DisplayLines
    std::vector<std::vector<DisplayLine>> all_display;

    for (int i = start; i < end; i++) {
        bool selected = (i == app.selected_idx);
        auto lines = render_visible_line(app.visible_lines[i], selected, term_cols);
        all_display.push_back(std::move(lines));
    }

    // If fullscreen, fill remaining with empty lines
    int content_display_lines = 0;
    for (auto& dl : all_display) content_display_lines += (int)dl.size();

    // Calculate frame width = max visible width across all display lines
    int max_width = 0;
    for (auto& dl_list : all_display) {
        for (auto& dl : dl_list) {
            if (dl.visible_width > max_width)
                max_width = dl.visible_width;
        }
    }

    // In fullscreen mode, frame_width = term_cols
    // In inline mode, frame_width = min(max_width, term_cols)
    if (app.fullscreen) {
        frame_width = term_cols;
    } else {
        frame_width = std::min(max_width, term_cols);
    }

    // Build output
    output.clear();

    // First line: CR + clear to EOL
    output += "\r";
    output += "\x1b[2K";

    bool first = true;
    int actual_lines = 0;

    for (int vi = 0; vi < (int)all_display.size(); vi++) {
        auto& dl_list = all_display[vi];
        for (int di = 0; di < (int)dl_list.size(); di++) {
            auto& dl = dl_list[di];

            if (!first) {
                output += "\r\n";
                output += "\x1b[2K";  // clear line... actually FTXUI doesn't use 2K for every line
                // Actually based on analysis, only the FIRST line uses 2K
                // but padding takes care of the rest
            }
            first = false;

            // Write content
            output += dl.content;

            // Add padding to frame_width
            int pad = frame_width - dl.visible_width;
            if (pad > 0) output += std::string(pad, ' ');

            actual_lines++;
        }
    }

    // Add empty lines if fullscreen and content is shorter
    if (app.fullscreen) {
        while (actual_lines < viewport_height) {
            output += "\r\n";
            output += std::string(frame_width, ' ');
            actual_lines++;
        }
    }

    frame_lines = actual_lines;
    app.display_lines_count = actual_lines;
    app.display_frame_width = frame_width;
}

// ============================================================
// Output management  
// ============================================================
static int g_prev_lines = 0;
static int g_prev_width = 0;

void write_all(int fd, const std::string& s) {
    size_t remaining = s.size();
    const char* ptr = s.c_str();
    while (remaining > 0) {
        ssize_t n = write(fd, ptr, remaining);
        if (n <= 0) break;
        ptr += n;
        remaining -= n;
    }
}

// Draw frame on screen
void draw(App& app) {
    std::string frame_output;
    int frame_lines, frame_width;
    render_frame(app, frame_output, frame_lines, frame_width);

    std::string out;
    out += "\r";
    out += "\x1b[2K";

    // Write first line content
    // Actually the render_frame already starts with \r\x1b[2K
    // Let me restructure...

    write_all(STDOUT_FILENO, frame_output);

    // After rendering, cursor is at end of last line (at col frame_width)
    // Need to go back to start of display
    if (frame_lines > 1) {
        // Go up (frame_lines - 1) lines
        std::ostringstream oss;
        oss << "\x1b[" << (frame_lines - 1) << "A";
        write_all(STDOUT_FILENO, oss.str());
    }
    // Go to col 0 (back by frame_width chars)
    if (frame_width > 0) {
        std::ostringstream oss;
        oss << "\x1b[" << frame_width << "D";
        write_all(STDOUT_FILENO, oss.str());
    }

    // Hide cursor
    write_all(STDOUT_FILENO, "\x1b[?25l");

    g_prev_lines = frame_lines;
    g_prev_width = frame_width;
}

// ============================================================
// Read keyboard input
// ============================================================
enum class Key {
    None,
    Up, Down, Left, Right,
    Enter,
    Escape,
    Q,
    G,
    Plus, Minus,
    PageUp, PageDown,
    Other
};

Key read_key() {
    unsigned char c;
    int n = read(STDIN_FILENO, &c, 1);
    if (n <= 0) return Key::None;

    if (c == 27) { // ESC
        // Check for escape sequence
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        struct timeval tv = {0, 50000}; // 50ms timeout
        int r = select(STDIN_FILENO + 1, &fds, nullptr, nullptr, &tv);
        if (r <= 0) return Key::Escape;

        unsigned char next;
        read(STDIN_FILENO, &next, 1);
        if (next == '[') {
            unsigned char seq[8];
            int len = 0;
            while (len < 7) {
                FD_ZERO(&fds);
                FD_SET(STDIN_FILENO, &fds);
                tv = {0, 50000};
                r = select(STDIN_FILENO + 1, &fds, nullptr, nullptr, &tv);
                if (r <= 0) break;
                read(STDIN_FILENO, &seq[len], 1);
                if (seq[len] >= 'A' && seq[len] <= 'z') { len++; break; }
                len++;
            }
            seq[len] = 0;

            // Parse CSI sequence
            if (len == 1) {
                switch (seq[0]) {
                    case 'A': return Key::Up;
                    case 'B': return Key::Down;
                    case 'C': return Key::Right;
                    case 'D': return Key::Left;
                }
            }
            if (len >= 2 && seq[len-1] == '~') {
                // Extended sequences
                std::string code(seq, seq + len - 1);
                if (code == "5") return Key::PageUp;
                if (code == "6") return Key::PageDown;
            }
            if (len >= 2 && seq[0] == '1' && seq[1] == ';') {
                // Handle 1;xX sequences (modified keys)
            }
        } else if (next == 'O') {
            unsigned char seq;
            read(STDIN_FILENO, &seq, 1);
            switch (seq) {
                case 'A': return Key::Up;
                case 'B': return Key::Down;
                case 'C': return Key::Right;
                case 'D': return Key::Left;
            }
        }
        return Key::Escape;
    }

    switch (c) {
        case '\r': case '\n': return Key::Enter;
        case 'q': case 'Q': return Key::Q;
        case 'g': return Key::G;
        case 'G': return Key::G; // Shift+G
        case 'j': return Key::Down;
        case 'k': return Key::Up;
        case 'h': return Key::Left;
        case 'l': return Key::Right;
        case '+': return Key::Plus;
        case '-': return Key::Minus;
    }

    return Key::Other;
}

// ============================================================
// Signal handler for resize
// ============================================================
static volatile bool g_resize = false;

void sigwinch_handler(int) {
    g_resize = true;
}

// ============================================================
// Final cleanup sequence (before exit)
// ============================================================
void final_render_and_cleanup(App& app, bool fullscreen) {
    // Do a final render
    std::string frame_output;
    int frame_lines, frame_width;
    render_frame(app, frame_output, frame_lines, frame_width);

    // Position sequence: go to bottom, then back to top, then CPR
    std::ostringstream pos_seq;
    if (frame_lines > 1) {
        pos_seq << "\x1b[" << (frame_lines - 1) << "B";
    }
    if (frame_width > 0) {
        pos_seq << "\x1b[" << frame_width << "C";
    }
    pos_seq << "\r";
    for (int i = 0; i < frame_lines - 1; i++) {
        pos_seq << "\x1b[1A";
    }
    pos_seq << "\x1b[6n";
    write_all(STDOUT_FILENO, pos_seq.str());

    // Write the frame
    write_all(STDOUT_FILENO, frame_output);

    // Back to top
    std::ostringstream back;
    if (frame_lines > 1) {
        back << "\x1b[" << (frame_lines - 1) << "A";
    }
    if (frame_width > 0) {
        back << "\x1b[" << frame_width << "D";
    }
    back << "\x1b[?25l";
    write_all(STDOUT_FILENO, back.str());

    // Go to bottom for final cleanup
    std::ostringstream cleanup;
    if (frame_lines > 1) {
        cleanup << "\x1b[" << (frame_lines - 1) << "B";
    }
    if (frame_width > 0) {
        cleanup << "\x1b[" << frame_width << "C";
    }

    // Cleanup sequences
    if (fullscreen) {
        cleanup << "\x1b[?1049l"; // exit alternate screen
    }
    cleanup << "\x1b[?1006l";  // disable SGR mouse
    cleanup << "\x1b[?1015l";  // disable URXVT mouse
    cleanup << "\x1b[?1003l";  // disable mouse any-event
    cleanup << "\x1b[?1000l";  // disable mouse button reporting
    cleanup << "\x1b[?7h";     // enable autowrap
    cleanup << "\x1b[?25h";    // show cursor
    cleanup << "\x1b[1 q";     // cursor shape (blinking block?)
    cleanup << "\x00";          // null
    cleanup << "\r\r\n";        // final newline

    write_all(STDOUT_FILENO, cleanup.str());
}

// ============================================================
// Startup sequence
// ============================================================
void startup_sequence(bool fullscreen) {
    std::string out;
    out += "\x00";              // null byte
    out += "\x1bP$q q\x1b\\"; // DCS cursor shape query
    if (fullscreen) {
        out += "\x1b[?1049h";  // enter alternate screen
    }
    out += "\x1b[?7l";         // disable autowrap
    out += "\x1b[?1000h";      // enable mouse button reporting
    out += "\x1b[?1003h";      // enable mouse any-event
    out += "\x1b[?1015h";      // enable URXVT mouse
    out += "\x1b[?1006h";      // enable SGR mouse
    write_all(STDOUT_FILENO, out);
}

// ============================================================
// Main loop
// ============================================================
void run(App& app) {
    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigwinch_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sigaction(SIGWINCH, &sa, nullptr);

    // Initial draw
    draw(app);

    while (app.running) {
        // Handle pending resize
        if (g_resize) {
            g_resize = false;
            get_term_size();
            // On resize: position sequence + CPR + redraw
            // Go to bottom of current display
            std::ostringstream pos;
            if (g_prev_lines > 1) {
                pos << "\x1b[" << (g_prev_lines - 1) << "B";
            }
            if (g_prev_width > 0) {
                pos << "\x1b[" << g_prev_width << "C";
            }
            pos << "\r";
            for (int i = 0; i < g_prev_lines - 1; i++) {
                pos << "\x1b[1A";
            }
            pos << "\x1b[6n";
            write_all(STDOUT_FILENO, pos.str());
            draw(app);
            continue;
        }

        // Wait for input with select
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        struct timeval tv = {0, 100000}; // 100ms
        int r = select(STDIN_FILENO + 1, &fds, nullptr, nullptr, &tv);
        if (r < 0) continue;
        if (r == 0) continue;

        Key key = read_key();

        bool need_redraw = false;

        switch (key) {
            case Key::Escape:
            case Key::Q:
                app.running = false;
                break;

            case Key::Up:
                app.move_selection(-1);
                app.last_key_was_g = false;
                need_redraw = true;
                break;

            case Key::Down:
                app.move_selection(1);
                app.last_key_was_g = false;
                need_redraw = true;
                break;

            case Key::Left:
            case Key::Right:
                // No-op for now (or collapse/expand?)
                app.last_key_was_g = false;
                break;

            case Key::Enter:
                app.toggle_selected();
                app.last_key_was_g = false;
                need_redraw = true;
                break;

            case Key::Plus:
                app.expand_selected();
                app.last_key_was_g = false;
                need_redraw = true;
                break;

            case Key::Minus:
                app.collapse_selected();
                app.last_key_was_g = false;
                need_redraw = true;
                break;

            case Key::G: {
                // Check: was last key also 'g'? If so, go to top (gg)
                // But 'G' (uppercase) = go to bottom always
                // Need to differentiate 'g' vs 'G'...
                // Actually the key reading returns Key::G for both
                // Let me check: in read_key, 'G' and 'g' both return Key::G
                // The 'gg' pattern: pressing 'g' twice = go to top
                // 'G' (single shift-g) = go to bottom
                // Since we can't distinguish in current code, let me check again...

                // Actually 'G' alone = go to bottom
                // 'g' then 'g' = go to top
                // The difference is uppercase vs lowercase
                // In read_key, I have: case 'G': return Key::G; // Shift+G
                // But I need two different keys here

                // For now: G = go to bottom
                // Need to fix key reading for gg
                app.selected_idx = (int)app.visible_lines.size() - 1;
                app.last_key_was_g = false;
                need_redraw = true;
                break;
            }

            case Key::PageUp: {
                int jump = std::max(1, g_prev_lines - 1);
                app.move_selection(-jump);
                need_redraw = true;
                break;
            }

            case Key::PageDown: {
                int jump = std::max(1, g_prev_lines - 1);
                app.move_selection(jump);
                need_redraw = true;
                break;
            }

            default:
                break;
        }

        if (need_redraw) {
            // Go back to start of display before redrawing
            // We're currently at (display_start, 0) = (cursor hidden, at top)
            // Actually after draw(), cursor is at display start (0,0)
            draw(app);
        }
    }
}

