int main(int argc, char** argv) {
    bool fullscreen = false;
    std::string filename;
    bool help = false;
    bool version = false;
    bool keybinding = false;
    bool end_of_flags = false;

    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (!end_of_flags && arg == "--") {
            end_of_flags = true;
            continue;
        }
        if (!end_of_flags) {
            if (arg == "-h" || arg == "--help") { help = true; continue; }
            if (arg == "-v" || arg == "--version") { version = true; continue; }
            if (arg == "-f" || arg == "--fullscreen") { fullscreen = true; continue; }
            if (arg == "-k" || arg == "--key" || arg == "--keybinding") { keybinding = true; continue; }
            if (arg[0] == '-') { help = true; continue; }
        }
        filename = arg;
    }

    if (version) {
        std::cout << "1.4.1\n";
        return 0;
    }

    if (help) {
        print_help(argv[0]);
        // Print twice like original
        print_help(argv[0]);
        return 0;
    }

    if (keybinding) {
        print_keybindings();
        return 0;
    }

    // Read JSON
    std::string json_str;
    if (filename.empty()) {
        // Read from stdin
        // Show message to tty
        if (isatty(STDIN_FILENO)) {
            std::cerr << "Reading from stdin..." << std::endl;
        }
        // Actually the message goes to tty, not stderr
        // Write "Reading from stdin... " to /dev/tty
        int tty_fd = open("/dev/tty", O_WRONLY);
