            return 1;
        }
        std::ostringstream ss;
        ss << f.rdbuf();
        json_str = ss.str();
    }

    // Parse JSON
    JsonPtr json = JsonParser::parse(json_str);

    // Initialize terminal
    get_term_size();

    // Run TUI
    App app(json, fullscreen);

    enable_raw_mode();

    // Startup sequence
    startup_sequence(fullscreen);

    // Run main loop
    run(app);

