// ANSI codes
static const char* RESET      = "\x1b[0m";
static const char* BOLD       = "\x1b[1m";
static const char* BOLD_OFF   = "\x1b[22m";
static const char* REVERSE    = "\x1b[7m";
static const char* REV_OFF    = "\x1b[27m";
static const char* FG_DEF     = "\x1b[39m";
static const char* BG_DEF     = "\x1b[49m";
static const char* FG_DGRAY   = "\x1b[90m";
static const char* FG_RED     = "\x1b[91m";
static const char* FG_GREEN   = "\x1b[92m";
static const char* FG_YELLOW  = "\x1b[93m";
static const char* FG_BLUE    = "\x1b[94m";
static const char* FG_CYAN    = "\x1b[96m";
static const char* FG_TEAL    = "\x1b[36m";

// JSON types
enum class JType { Null, Bool, Number, String, Array, Object };

struct JVal;
using JPtr = std::shared_ptr<JVal>;

struct JVal {
    JType type = JType::Null;
    bool bval = false;
    double nval = 0.0;
    std::string sval;
    std::vector<JPtr> aval;
    std::vector<std::pair<std::string, JPtr>> oval;

    static JPtr make_null() { auto v=std::make_shared<JVal>(); v->type=JType::Null; return v; }
    static JPtr make_bool(bool b) { auto v=std::make_shared<JVal>(); v->type=JType::Bool; v->bval=b; return v; }
    static JPtr make_num(double n) { auto v=std::make_shared<JVal>(); v->type=JType::Number; v->nval=n; return v; }
    static JPtr make_str(std::string s) { auto v=std::make_shared<JVal>(); v->type=JType::String; v->sval=std::move(s); return v; }
    static JPtr make_arr() { auto v=std::make_shared<JVal>(); v->type=JType::Array; return v; }
    static JPtr make_obj() { auto v=std::make_shared<JVal>(); v->type=JType::Object; return v; }
};

class JsonParser {
    std::string in;
    size_t pos=0;
public:
    explicit JsonParser(std::string s): in(std::move(s)) {}
    void skip() { while(pos<in.size()&&(in[pos]==' '||in[pos]=='\t'||in[pos]=='\n'||in[pos]=='\r'))pos++; }
    char peek() { return pos<in.size()?in[pos]:0; }
    char next() { return pos<in.size()?in[pos++]:0; }
    bool eat(char c) { skip(); if(peek()==c){next();return true;} return false; }

    std::string parse_str() {
        eat('"');
        std::string r;
        while(pos<in.size()&&in[pos]!='"') {
            if(in[pos]=='\\') {
                pos++;
                char e=next();
                if(e=='"')r+='"'; else if(e=='\\')r+='\\'; else if(e=='/')r+='/';
                else if(e=='b')r+='\b'; else if(e=='f')r+='\f'; else if(e=='n')r+='\n';
                else if(e=='r')r+='\r'; else if(e=='t')r+='\t';
                else if(e=='u') {
                    std::string h; for(int i=0;i<4&&pos<in.size();i++) h+=next();
                    unsigned cp=0; try{cp=stoul(h,nullptr,16);}catch(...){}
                    if(cp<0x80) r+=(char)cp;
                    else if(cp<0x800){r+=(char)(0xC0|(cp>>6));r+=(char)(0x80|(cp&0x3F));}
                    else{r+=(char)(0xE0|(cp>>12));r+=(char)(0x80|((cp>>6)&0x3F));r+=(char)(0x80|(cp&0x3F));}
                } else r+=e;
            } else r+=next();
        }
        eat('"');
        return r;
    }

    JPtr parse_val() {
        skip();
        if(pos>=in.size()) return JVal::make_null();
        char c=peek();
        if(c=='"') return JVal::make_str(parse_str());
        if(c=='{') return parse_obj();
        if(c=='[') return parse_arr();
        if(c=='t'){pos+=4;return JVal::make_bool(true);}
        if(c=='f'){pos+=5;return JVal::make_bool(false);}
        if(c=='n'){pos+=4;return JVal::make_null();}
        if(c=='-'||(c>='0'&&c<='9')) {
            std::string s;
            if(peek()=='-')s+=next();
            while(pos<in.size()&&in[pos]>='0'&&in[pos]<='9')s+=next();
            if(pos<in.size()&&in[pos]=='.'){s+=next();while(pos<in.size()&&in[pos]>='0'&&in[pos]<='9')s+=next();}
            if(pos<in.size()&&(in[pos]=='e'||in[pos]=='E')){
                s+=next();if(pos<in.size()&&(in[pos]=='+'||in[pos]=='-'))s+=next();
                while(pos<in.size()&&in[pos]>='0'&&in[pos]<='9')s+=next();
            }
            double v=0; try{v=stod(s);}catch(...){}
            return JVal::make_num(v);
        }
        return JVal::make_null();
    }

    JPtr parse_obj() {
        eat('{');
        auto o=JVal::make_obj();
        skip(); if(peek()=='}'){next();return o;}
        while(pos<in.size()) {
            skip(); if(peek()!='"') break;
            std::string k=parse_str(); eat(':');
            o->oval.push_back({k,parse_val()});
            skip(); if(peek()==','){next();continue;} if(peek()=='}'){next();break;} break;
        }
        std::sort(o->oval.begin(),o->oval.end(),[](auto&a,auto&b){return a.first<b.first;});
        return o;
    }

    JPtr parse_arr() {
        eat('[');
        auto a=JVal::make_arr();
        skip(); if(peek()==']'){next();return a;}
        while(pos<in.size()) {
            a->aval.push_back(parse_val());
            skip(); if(peek()==','){next();continue;} if(peek()==']'){next();break;} break;
        }
        return a;
    }

    static JPtr parse(const std::string& s) {
        JsonParser p(s); p.skip(); return p.parse_val();
    }
};

// Format number
static std::string fmt_num(double v) {
    if(v==(long long)v && v>=-1e15 && v<=1e15) return std::to_string((long long)v);
    std::ostringstream ss; ss<<v; return ss.str();
}

// Terminal size
static int ROWS=24, COLS=80;
void get_term_size() {
    struct winsize ws;
    if(ioctl(STDOUT_FILENO,TIOCGWINSZ,&ws)==0) {
        ROWS=ws.ws_row>0?ws.ws_row:24;
        COLS=ws.ws_col>0?ws.ws_col:80;
    }
}

// Raw mode
static struct termios orig_term;
static bool raw_active=false;
void enable_raw() {
    if(!isatty(STDIN_FILENO)) return;
    tcgetattr(STDIN_FILENO,&orig_term);
    struct termios r=orig_term;
    r.c_iflag&=~(BRKINT|ICRNL|INPCK|ISTRIP|IXON);
    r.c_oflag&=~OPOST;
    r.c_cflag|=CS8;
    r.c_lflag&=~(ECHO|ICANON|IEXTEN|ISIG);
    r.c_cc[VMIN]=1; r.c_cc[VTIME]=0;
    tcsetattr(STDIN_FILENO,TCSAFLUSH,&r);
    raw_active=true;
}
void disable_raw() {
    if(raw_active){tcsetattr(STDIN_FILENO,TCSAFLUSH,&orig_term);raw_active=false;}
}

// Tree node
struct Node {
    JPtr val;
    std::string key;
    int depth;
    bool expanded=false;
    bool is_last=true;
    bool is_table=false;
    std::vector<Node> children;
    Node(JPtr v,std::string k,int d,bool last): val(v),key(std::move(k)),depth(d),is_last(last) {}
};

bool is_table_arr(const JPtr& v) {
    if(v->type!=JType::Array) return false;
    if(v->aval.size()<2) return false;
    for(auto& e:v->aval) if(e->type!=JType::Object) return false;
    return true;
}

Node build(JPtr v, std::string key, int depth, bool last) {
    Node n(v,std::move(key),depth,last);
    // Initial expansion:
    // depth 0: always expanded
    // depth 1 objects: expanded
    // depth 2+: collapsed
    if(depth==0) n.expanded=true;
    else if(depth==1 && v->type==JType::Object) n.expanded=true;
    else n.expanded=false;

    n.is_table=is_table_arr(v);

    if(v->type==JType::Object) {
        size_t sz=v->oval.size();
        for(size_t i=0;i<sz;i++)
            n.children.push_back(build(v->oval[i].second,v->oval[i].first,depth+1,i==sz-1));
    } else if(v->type==JType::Array) {
        size_t sz=v->aval.size();
        for(size_t i=0;i<sz;i++)
            n.children.push_back(build(v->aval[i],"",depth+1,i==sz-1));
    }
    return n;
}

// Visible lines
struct VLine {
    Node* node;
    bool is_close;
    VLine(Node* n, bool c): node(n), is_close(c) {}
};

void collect(Node& n, std::vector<VLine>& lines) {
    JType t=n.val->type;
    if(t==JType::Object||t==JType::Array) {
        lines.push_back({&n,false});
        if(n.expanded) {
            for(auto& c:n.children) collect(c,lines);
            lines.push_back({&n,true});
        }
    } else {
        lines.push_back({&n,false});
    }
}

// Write all bytes
void write_all(const std::string& s) {
    if(s.empty()) return;
    const char* p=s.data(); size_t left=s.size();
    while(left>0){ssize_t n=write(STDOUT_FILENO,p,left);if(n<=0)break;p+=n;left-=n;}
}

// Key enum
enum class Key { None,Up,Down,Left,Right,Enter,Esc,LittleG,BigG,Plus,Minus,PageUp,PageDown,Other };

Key read_key() {
    unsigned char c;
    if(read(STDIN_FILENO,&c,1)<=0) return Key::None;
    if(c==27) {
        fd_set f; FD_ZERO(&f); FD_SET(STDIN_FILENO,&f);
        struct timeval tv={0,50000};
        if(select(STDIN_FILENO+1,&f,0,0,&tv)<=0) return Key::Esc;
        unsigned char n2; read(STDIN_FILENO,&n2,1);
        if(n2=='[') {
            char seq[16]; int len=0;
            while(len<15) {
                FD_ZERO(&f); FD_SET(STDIN_FILENO,&f); tv={0,50000};
                if(select(STDIN_FILENO+1,&f,0,0,&tv)<=0) break;
                read(STDIN_FILENO,(unsigned char*)&seq[len],1);
                if(seq[len]>='A'&&seq[len]<='Z'){len++;break;}
                if(seq[len]=='~'){len++;break;}
                len++;
            }
            seq[len]=0;
            if(len==1){if(seq[0]=='A')return Key::Up;if(seq[0]=='B')return Key::Down;if(seq[0]=='C')return Key::Right;if(seq[0]=='D')return Key::Left;}
            if(len>=2&&seq[len-1]=='~'){
                std::string code(seq,len-1);
                if(code=="5")return Key::PageUp;
                if(code=="6")return Key::PageDown;
            }
        } else if(n2=='O') {
            unsigned char s2; read(STDIN_FILENO,&s2,1);
            if(s2=='A')return Key::Up;if(s2=='B')return Key::Down;if(s2=='C')return Key::Right;if(s2=='D')return Key::Left;
        }
        return Key::Esc;
    }
    switch(c) {
        case '\r': case '\n': return Key::Enter;
        case 'q': case 'Q': return Key::Esc;
        case 27: return Key::Esc;
        case 'j': return Key::Down;
        case 'k': return Key::Up;
        case 'h': return Key::Left;
        case 'l': return Key::Right;
        case '+': return Key::Plus;
        case '-': return Key::Minus;
        case 'g': return Key::LittleG;
        case 'G': return Key::BigG;
    }
    return Key::Other;
}

// Resize signal
static volatile bool g_resize=false;
void sig_winch(int) { g_resize=true; }

// App state
struct App {
    Node root;
    std::vector<VLine> vlines;
    int sel=0;
    int scroll=0;
    bool fullscreen;
    bool running=true;
    bool last_g=false;
    int prev_lines=0;
    int prev_width=0;

    App(JPtr json, bool fs): root(build(json,"",0,true)), fullscreen(fs) {
        root.is_last=true;
        rebuild();
    }

    void rebuild() {
        vlines.clear();
        collect(root,vlines);
        if(sel>=(int)vlines.size()) sel=(int)vlines.size()-1;
        if(sel<0) sel=0;
    }

    void ensure_visible() {
        int vh=viewport_height();
        if(vh<=0) vh=1;
        if(sel<scroll) scroll=sel;
        else if(sel>=scroll+vh) scroll=sel-vh+1;
        if(scroll<0) scroll=0;
        int mx=(int)vlines.size()-vh;
        if(mx<0) mx=0;
        if(scroll>mx) scroll=mx;
    }

    int viewport_height() {
        if(fullscreen) return ROWS;
        return std::min((int)vlines.size(), ROWS);
    }

    void move_sel(int d) {
        sel+=d;
        if(sel<0) sel=0;
        if(sel>=(int)vlines.size()) sel=(int)vlines.size()-1;
    }

    void toggle() {
        if(sel<0||sel>=(int)vlines.size()) return;
        VLine& vl=vlines[sel];
        if(vl.is_close) return;
        Node* n=vl.node;
        if(n->val->type!=JType::Object&&n->val->type!=JType::Array) return;
        n->expanded=!n->expanded;
        rebuild();
    }

    void deep_expand(Node& n) {
        if(n.val->type==JType::Object||n.val->type==JType::Array){
            n.expanded=true;
            for(auto& c:n.children) deep_expand(c);
        }
    }
    void deep_collapse(Node& n) {
        if(n.val->type==JType::Object||n.val->type==JType::Array){
            n.expanded=false;
            for(auto& c:n.children) deep_collapse(c);
        }
    }
    void do_expand() {
        if(sel<0||sel>=(int)vlines.size()) return;
        VLine& vl=vlines[sel];
        if(vl.is_close) return;
        deep_expand(*vl.node);
        rebuild();
    }
    void do_collapse() {
        if(sel<0||sel>=(int)vlines.size()) return;
        VLine& vl=vlines[sel];
        if(vl.is_close) return;
        deep_collapse(*vl.node);
        rebuild();
    }
};

// Make key prefix: returns (ansi_string, visible_len)
static std::pair<std::string,int> key_prefix(const std::string& key, int depth) {
    std::string ind(depth*2,' ');
    if(key.empty()) return {ind,(int)ind.size()};
    std::string qkey="\""+key+"\"";
    return {ind+FG_BLUE+qkey+FG_DEF+": ", (int)ind.size()+(int)qkey.size()+2};
}

// Word wrap
static std::vector<std::string> word_wrap(const std::string& text, int width) {
    if(width<=0) return {text};
    std::vector<std::string> words, result;
    std::string w;
    for(char c:text){if(c==' '){if(!w.empty()){words.push_back(w);w="";}}else w+=c;}
    if(!w.empty()) words.push_back(w);
    if(words.empty()){result.push_back(""); return result;}
    std::string line;
    for(auto& wd:words){
        if(line.empty()) line=wd;
        else if((int)(line.size()+1+wd.size())<=width) line+=' '+wd;
        else{result.push_back(line);line=wd;}
    }
    if(!line.empty()) result.push_back(line);
    return result;
}

struct DLine {
    std::string content;
    int vwidth;
};

// Render visible line to display lines
static std::vector<DLine> render_vline(const VLine& vl, bool sel, int term_cols) {
    Node* nd=vl.node;
    JPtr v=nd->val;
    int depth=nd->depth;
    std::string ind(depth*2,' ');

    std::vector<DLine> res;

    if(vl.is_close) {
        char br=(v->type==JType::Object)?'}':']';
        std::string comma=nd->is_last?"":",";
        std::string out=ind;
        if(sel) out+=REVERSE;
        out+=br;
        if(sel) out+=REV_OFF;
        out+=FG_DEF; out+=BG_DEF;
        out+=comma;
        res.push_back({out,(int)ind.size()+1+(int)comma.size()});
        return res;
    }

    auto [kpfx,klen]=key_prefix(nd->key,depth);

    if(v->type==JType::Object||v->type==JType::Array) {
        char ob=(v->type==JType::Object)?'{':'[';
        char cb=(v->type==JType::Object)?'}':']';
        std::string comma=nd->is_last?"":",";

        if(!nd->expanded) {
            std::string ct=std::string(1,ob)+"..."+cb+comma;
            std::string out=kpfx+BOLD;
            if(sel) out+=REVERSE;
            out+=ct;
            if(sel) out+=REV_OFF;
            out+=RESET; out+=FG_DEF; out+=BG_DEF;
            res.push_back({out,klen+(int)ct.size()});
        } else {
            std::string table_hint="";
            int table_hint_len=0;
            if(nd->is_table) {
                table_hint=std::string("   ")+FG_DGRAY+"(table view)"+FG_DEF;
                table_hint_len=15; // "   (table view)" = 15 chars
            }
            std::string out=kpfx+BOLD;
            if(sel) out+=REVERSE;
            out+=ob;
            if(sel) out+=REV_OFF;
            out+=RESET; out+=FG_DEF; out+=BG_DEF;
            out+=table_hint;
            res.push_back({out,klen+1+table_hint_len});
        }
        return res;
    }

    // Scalar
    std::string comma=nd->is_last?"":",";
    const char* col=FG_DEF;
    if(v->type==JType::Null) col=FG_RED;
    else if(v->type==JType::Bool) col=FG_YELLOW;
    else if(v->type==JType::Number) col=FG_CYAN;
    else if(v->type==JType::String) col=FG_GREEN;

    std::string txt;
    if(v->type==JType::Null) txt="null";
    else if(v->type==JType::Bool) txt=(v->bval?"true":"false");
    else if(v->type==JType::Number) txt=fmt_num(v->nval);
    else txt="\""+v->sval+"\"";

    std::string full=txt+comma;
    int avail=term_cols-klen;

    if(avail>0&&(int)full.size()>avail) {
        // Word wrap
        auto parts=word_wrap(full,avail);
        for(int i=0;i<(int)parts.size();i++) {
            std::string out;
            if(i==0) {
                out=kpfx+col+BG_DEF;
                if(sel) out+=REVERSE;
                out+=parts[i];
                if(sel) out+=REV_OFF;
                out+=FG_DEF+BG_DEF;
            } else {
                // continuation: indent + key_as_spaces + ": "
                out=std::string(depth*2,' ');
                if(!nd->key.empty()) {
                    std::string ksp(nd->key.size()+2,' ');
                    out+=FG_BLUE+ksp+FG_DEF+"  ";
                }
                out+=col+BG_DEF;
                out+=parts[i];
                out+=FG_DEF+BG_DEF;
            }
            res.push_back({out,klen+(int)parts[i].size()});
        }
    } else {
        std::string out=kpfx+col+BG_DEF;
        if(sel) out+=REVERSE;
        out+=full;
        if(sel) out+=REV_OFF;
        out+=FG_DEF+BG_DEF;
        res.push_back({out,klen+(int)full.size()});
    }
    return res;
}

// Draw frame, returns (lines_drawn, frame_width)
std::pair<int,int> draw_frame(App& app) {
    get_term_size();
    app.ensure_visible();

    int vh=app.viewport_height();
    int total=(int)app.vlines.size();
    int start=app.scroll;
    int end2=std::min(start+vh,total);

    // Collect display lines
    std::vector<DLine> all_dlines;
    for(int i=start;i<end2;i++) {
        bool sel=(i==app.sel);
        auto dl=render_vline(app.vlines[i],sel,COLS);
        for(auto& d:dl) all_dlines.push_back(d);
    }

    // Fill to viewport_height in fullscreen
    if(app.fullscreen) {
        while((int)all_dlines.size()<vh) all_dlines.push_back({"",0});
    }

    // Compute frame width
    int fw=0;
    for(auto& d:all_dlines) if(d.vwidth>fw) fw=d.vwidth;
    if(app.fullscreen) fw=COLS;
    else fw=std::min(fw,COLS);

    // Render to string
    std::string out;
    out+="\r\x1b[2K";
    for(int i=0;i<(int)all_dlines.size();i++) {
        if(i>0) { out+="\r\n\x1b[2K"; }
        out+=all_dlines[i].content;
        int pad=fw-all_dlines[i].vwidth;
        if(pad>0) out+=std::string(pad,' ');
    }

    write_all(out);

    int nlines=(int)all_dlines.size();
    // Move cursor back to top-left of display
    if(nlines>1) { std::string s="\x1b["; s+=std::to_string(nlines-1); s+="A"; write_all(s); }
    if(fw>0) { std::string s="\x1b["; s+=std::to_string(fw); s+="D"; write_all(s); }
    write_all("\x1b[?25l");
    write_all("\x00");

    return {nlines, fw};
}

void do_redraw(App& app) {
    auto [nl,fw]=draw_frame(app);
    app.prev_lines=nl;
    app.prev_width=fw;
}

void on_event_or_resize(App& app) {
    // Position cursor + CPR + redraw
    std::string s;
    if(app.prev_lines>1){s+="\x1b["; s+=std::to_string(app.prev_lines-1); s+="B";}
    if(app.prev_width>0){s+="\x1b["; s+=std::to_string(app.prev_width); s+="C";}
    s+="\r";
    for(int i=0;i<app.prev_lines-1;i++) s+="\x1b[1A";
    s+="\x1b[6n";
    write_all(s);
    do_redraw(app);
}

void run(App& app) {
    struct sigaction sa; sa.sa_handler=sig_winch;
    sigemptyset(&sa.sa_mask); sa.sa_flags=SA_RESTART;
    sigaction(SIGWINCH,&sa,nullptr);

    do_redraw(app);

    while(app.running) {
        if(g_resize) {
            g_resize=false;
            get_term_size();
            on_event_or_resize(app);
            continue;
        }

        fd_set fds; FD_ZERO(&fds); FD_SET(STDIN_FILENO,&fds);
        struct timeval tv={0,100000};
        if(select(STDIN_FILENO+1,&fds,0,0,&tv)<=0) continue;

        Key k=read_key();
        bool need=false;

        switch(k) {
            case Key::Esc: app.running=false; break;
            case Key::Up: app.move_sel(-1); app.last_g=false; need=true; break;
            case Key::Down: app.move_sel(1); app.last_g=false; need=true; break;
            case Key::Left: case Key::Right: app.last_g=false; break;
            case Key::Enter: app.toggle(); app.last_g=false; need=true; break;
            case Key::Plus: app.do_expand(); app.last_g=false; need=true; break;
            case Key::Minus: app.do_collapse(); app.last_g=false; need=true; break;
            case Key::BigG:
                app.sel=(int)app.vlines.size()-1;
                app.last_g=false; need=true; break;
            case Key::LittleG:
                if(app.last_g) {
                    // gg = go to top
                    app.sel=0;
                    app.last_g=false; need=true;
                } else {
                    app.last_g=true;
                }
                break;
            case Key::PageUp: {
                int jump=std::max(1,app.prev_lines-1);
                app.move_sel(-jump); app.last_g=false; need=true; break;
            }
            case Key::PageDown: {
                int jump=std::max(1,app.prev_lines-1);
                app.move_sel(jump); app.last_g=false; need=true; break;
            }
            default: app.last_g=false; break;
        }

        if(need) on_event_or_resize(app);
    }
}

