#define REV_OFF    "\x1b[27m"
#define RESET      "\x1b[0m"

// JSON types
enum class JType { Null, Bool, Number, String, Array, Object };

struct JVal;
using JPtr = std::shared_ptr<JVal>;

struct JVal {
    JType type = JType::Null;
    bool bval = false;
    double nval = 0.0;
    std::string sval;
    std::vector<JPtr> aval;
    std::vector<std::pair<std::string, JPtr>> oval;
    static JPtr make_null() { auto v=std::make_shared<JVal>(); v->type=JType::Null; return v; }
    static JPtr make_bool(bool b) { auto v=std::make_shared<JVal>(); v->type=JType::Bool; v->bval=b; return v; }
    static JPtr make_num(double n) { auto v=std::make_shared<JVal>(); v->type=JType::Number; v->nval=n; return v; }
    static JPtr make_str(std::string s) { auto v=std::make_shared<JVal>(); v->type=JType::String; v->sval=std::move(s); return v; }
    static JPtr make_arr() { auto v=std::make_shared<JVal>(); v->type=JType::Array; return v; }
    static JPtr make_obj() { auto v=std::make_shared<JVal>(); v->type=JType::Object; return v; }
};

class JsonParser {
    std::string in; size_t pos=0;
public:
    explicit JsonParser(std::string s): in(std::move(s)) {}
    void skip() { while(pos<in.size()&&(in[pos]==' '||in[pos]=='\t'||in[pos]=='\n'||in[pos]=='\r'))pos++; }
    char peek() { return pos<in.size()?in[pos]:0; }
    char next() { return pos<in.size()?in[pos++]:0; }
    bool eat(char c) { skip(); if(peek()==c){next();return true;} return false; }
    std::string parse_str() {
        eat('"'); std::string r;
        while(pos<in.size()&&in[pos]!='"') {
            if(in[pos]=='\\') {
                pos++; char e=next();
                if(e=='"')r+='"'; else if(e=='\\')r+='\\'; else if(e=='/')r+='/';
                else if(e=='b')r+='\b'; else if(e=='f')r+='\f'; else if(e=='n')r+='\n';
                else if(e=='r')r+='\r'; else if(e=='t')r+='\t';
                else if(e=='u') {
                    std::string h; for(int i=0;i<4&&pos<in.size();i++) h+=next();
                    unsigned cp=0; try{cp=stoul(h,nullptr,16);}catch(...){}
                    if(cp<0x80) r+=(char)cp;
                    else if(cp<0x800){r+=(char)(0xC0|(cp>>6));r+=(char)(0x80|(cp&0x3F));}
                    else{r+=(char)(0xE0|(cp>>12));r+=(char)(0x80|((cp>>6)&0x3F));r+=(char)(0x80|(cp&0x3F));}
                } else r+=e;
            } else r+=next();
        }
        eat('"'); return r;
    }
    JPtr parse_val() {
        skip(); if(pos>=in.size()) return JVal::make_null();
        char c=peek();
        if(c=='"') return JVal::make_str(parse_str());
        if(c=='{') return parse_obj(); if(c=='[') return parse_arr();
        if(c=='t'){pos+=4;return JVal::make_bool(true);}
        if(c=='f'){pos+=5;return JVal::make_bool(false);}
        if(c=='n'){pos+=4;return JVal::make_null();}
        if(c=='-'||(c>='0'&&c<='9')) {
            std::string s; if(peek()=='-')s+=next();
            while(pos<in.size()&&in[pos]>='0'&&in[pos]<='9')s+=next();
            if(pos<in.size()&&in[pos]=='.'){s+=next();while(pos<in.size()&&in[pos]>='0'&&in[pos]<='9')s+=next();}
            if(pos<in.size()&&(in[pos]=='e'||in[pos]=='E')){
                s+=next();if(pos<in.size()&&(in[pos]=='+'||in[pos]=='-'))s+=next();
                while(pos<in.size()&&in[pos]>='0'&&in[pos]<='9')s+=next();}
            double v=0; try{v=stod(s);}catch(...){} return JVal::make_num(v);
        }
        return JVal::make_null();
    }
    JPtr parse_obj() {
        eat('{'); auto o=JVal::make_obj(); skip(); if(peek()=='}'){next();return o;}
        while(pos<in.size()) {
            skip(); if(peek()!='"') break;
            std::string k=parse_str(); eat(':'); o->oval.push_back({k,parse_val()});
            skip(); if(peek()==','){next();continue;} if(peek()=='}'){next();break;} break;
        }
        std::sort(o->oval.begin(),o->oval.end(),[](auto&a,auto&b){return a.first<b.first;});
        return o;
    }
    JPtr parse_arr() {
        eat('['); auto a=JVal::make_arr(); skip(); if(peek()==']'){next();return a;}
        while(pos<in.size()) {
            a->aval.push_back(parse_val());
            skip(); if(peek()==','){next();continue;} if(peek()==']'){next();break;} break;
        }
        return a;
    }
    static JPtr parse(const std::string& s) { JsonParser p(s); p.skip(); return p.parse_val(); }
};

static std::string fmt_num(double v) {
    if(v==(long long)v && v>=-1e15 && v<=1e15) return std::to_string((long long)v);
    std::ostringstream ss; ss<<v; return ss.str();
}

static int ROWS=24, COLS=80;
void get_term_size() {
    struct winsize ws;
    if(ioctl(STDOUT_FILENO,TIOCGWINSZ,&ws)==0){ROWS=ws.ws_row>0?ws.ws_row:24;COLS=ws.ws_col>0?ws.ws_col:80;}
}

static struct termios orig_term;
static bool raw_active=false;
void enable_raw() {
    if(!isatty(STDIN_FILENO)) return;
    tcgetattr(STDIN_FILENO,&orig_term);
    struct termios r=orig_term;
    r.c_iflag&=~(BRKINT|ICRNL|INPCK|ISTRIP|IXON);
    r.c_oflag&=~OPOST; r.c_cflag|=CS8;
    r.c_lflag&=~(ECHO|ICANON|IEXTEN|ISIG);
    r.c_cc[VMIN]=1; r.c_cc[VTIME]=0;
    tcsetattr(STDIN_FILENO,TCSAFLUSH,&r); raw_active=true;
}
void disable_raw() { if(raw_active){tcsetattr(STDIN_FILENO,TCSAFLUSH,&orig_term);raw_active=false;} }

// Tree node
struct Node {
    JPtr val; std::string key; int depth; bool expanded=false; bool is_last=true; bool is_table=false;
    std::vector<Node> children;
    Node(JPtr v,std::string k,int d,bool last): val(v),key(std::move(k)),depth(d),is_last(last) {}
};

bool is_table_arr(const JPtr& v) {
    if(v->type!=JType::Array) return false; if(v->aval.size()<2) return false;
    for(auto& e:v->aval) if(e->type!=JType::Object) return false; return true;
}

Node build(JPtr v, std::string key, int depth, bool last) {
    Node n(v,std::move(key),depth,last);
    if(depth==0) n.expanded=true;
    else if(depth==1&&v->type==JType::Object) n.expanded=true;
    else n.expanded=false;
    n.is_table=is_table_arr(v);
    if(v->type==JType::Object) {
        size_t sz=v->oval.size();
        for(size_t i=0;i<sz;i++) n.children.push_back(build(v->oval[i].second,v->oval[i].first,depth+1,i==sz-1));
    } else if(v->type==JType::Array) {
        size_t sz=v->aval.size();
        for(size_t i=0;i<sz;i++) n.children.push_back(build(v->aval[i],"",depth+1,i==sz-1));
    }
    return n;
}

// Visible line - only NAVIGABLE items (no closing braces)
struct VLine {
    Node* node; bool is_close;
    VLine(Node* n, bool c): node(n), is_close(c) {}
};

// Collect ALL display lines (including closing braces)
// navigable[] tells which lines are navigable
struct DLine {
    std::string content; int vwidth; bool navigable;
};

// Word wrap
static std::vector<std::string> word_wrap(const std::string& text, int width) {
    if(width<=0) return {text};
    std::vector<std::string> words, result; std::string w;
    for(char c:text){if(c==' '){if(!w.empty()){words.push_back(w);w="";}}else w+=c;}
    if(!w.empty()) words.push_back(w);
    if(words.empty()){result.push_back(""); return result;}
    std::string line;
    for(auto& wd:words){
        if(line.empty()) line=wd;
        else if((int)(line.size()+1+wd.size())<=width) line+=' '+wd;
        else{result.push_back(line);line=wd;}
    }
    if(!line.empty()) result.push_back(line);
    return result;
}

// Render a Node to DLines
// sel: is this node selected (for OPENING lines only)
static std::vector<DLine> render_node(Node* node, bool selected, bool is_close, int term_cols) {
    JPtr v = node->val;
    int depth = node->depth;
    std::string ind(depth*2,' ');
    std::vector<DLine> res;

    if(is_close) {
        // Closing brace - plain text, not navigable
        char br=(v->type==JType::Object)?'}':']';
        std::string comma=node->is_last?"":",";
        std::string text=ind+br+comma;
        res.push_back({text,(int)text.size(),false});
        return res;
    }

    // Build key prefix string and visible length
    std::string kpfx_str;
    int kpfx_len;
    if(node->key.empty()) {
        kpfx_str=ind; kpfx_len=(int)ind.size();
    } else {
        std::string qk="\""+node->key+"\"";
        kpfx_str=ind+FG_BLUE+BG_DEF+qk+FG_DEF+BG_DEF+": ";
        kpfx_len=(int)ind.size()+(int)qk.size()+2;
    }

    if(v->type==JType::Object||v->type==JType::Array) {
        char ob=(v->type==JType::Object)?'{':'[';
        char cb=(v->type==JType::Object)?'}':']';
        std::string comma=node->is_last?"":",";

        if(!node->expanded) {
            // Collapsed: key_prefix + ATTR + "{...}," + ATTR_OFF
            std::string ct=std::string(1,ob)+"..."+cb+comma;
            std::string out=kpfx_str;
            if(selected) { out+=REVERSE; out+=ct; out+=REV_OFF; }
            else { out+=BOLD; out+=ct; out+=BOLD_OFF; }
            int vis=kpfx_len+(int)ct.size();
            res.push_back({out,vis,true});
        } else {
            // Expanded: key_prefix + ATTR + "{" + ATTR_OFF + [table_hint]
            std::string table_hint=""; int table_hint_len=0;
            if(node->is_table) { table_hint=std::string("   ")+FG_DGRAY+"(table view)"+FG_DEF; table_hint_len=15; }
            std::string out=kpfx_str;
            if(selected) { out+=REVERSE; out+=ob; out+=REV_OFF; out+=FG_DEF+BG_DEF; }
            else { out+=BOLD; out+=ob; out+=BOLD_OFF; }
            out+=table_hint;
            int vis=kpfx_len+1+table_hint_len;
            res.push_back({out,vis,true});
        }
        return res;
    }

    // Scalar
    std::string comma=node->is_last?"":",";
    const char* col=FG_DEF;
    if(v->type==JType::Null) col=FG_RED;
    else if(v->type==JType::Bool) col=FG_YELLOW;
    else if(v->type==JType::Number) col=FG_CYAN;
    else if(v->type==JType::String) col=FG_GREEN;

    std::string txt;
    if(v->type==JType::Null) txt="null";
    else if(v->type==JType::Bool) txt=(v->bval?"true":"false");
    else if(v->type==JType::Number) txt=fmt_num(v->nval);
    else txt="\""+v->sval+"\"";

    int avail=term_cols-kpfx_len;
    std::string full_val=txt+comma; // value + comma (comma will be plain)

    if(avail>0&&(int)full_val.size()>avail) {
        // Word wrap
        auto parts=word_wrap(full_val,avail);
        for(int i=0;i<(int)parts.size();i++) {
            std::string out;
            bool is_first=(i==0);
            if(is_first) {
                out=kpfx_str;
                if(selected) { out+=REVERSE; out+=col; out+=BG_DEF; out+=parts[i]; out+=REV_OFF; out+=FG_DEF; out+=BG_DEF; }
                else { out+=col; out+=BG_DEF; out+=parts[i]; out+=FG_DEF; out+=BG_DEF; }
            } else {
                // Continuation: indent + key_as_spaces + "  "
                out=ind;
                if(!node->key.empty()) {
                    std::string ksp(node->key.size()+2,' ');
                    out+=FG_BLUE+BG_DEF+ksp+FG_DEF+BG_DEF+"  ";
                }
                out+=col; out+=BG_DEF; out+=parts[i]; out+=FG_DEF; out+=BG_DEF;
            }
            res.push_back({out,kpfx_len+(int)parts[i].size(),is_first});
        }
    } else {
        // Single line
        // Split txt and comma for proper coloring
        std::string out=kpfx_str;
        if(selected) { out+=REVERSE; out+=col; out+=BG_DEF; out+=txt; out+=REV_OFF; out+=FG_DEF; out+=BG_DEF; out+=comma; }
        else { out+=col; out+=BG_DEF; out+=txt; out+=FG_DEF; out+=BG_DEF; out+=comma; }
        res.push_back({out,kpfx_len+(int)txt.size()+(int)comma.size(),true});
    }
    return res;
}

// Collect display lines for entire tree
void collect_dlines(Node& node, std::vector<DLine>& dlines, int sel_node_idx, int& nav_idx, int term_cols) {
    JPtr v=node.val;
    if(v->type==JType::Object||v->type==JType::Array) {
        bool sel=(nav_idx==sel_node_idx);
        int my_nav_idx=nav_idx;
        nav_idx++;
        auto lines=render_node(&node,sel,false,term_cols);
        for(auto& l:lines) dlines.push_back(l);
        if(node.expanded) {
            for(auto& c:node.children) collect_dlines(c,dlines,sel_node_idx,nav_idx,term_cols);
            // Closing brace (not navigable)
            auto cl=render_node(&node,false,true,term_cols);
            for(auto& l:cl) dlines.push_back(l);
        }
    } else {
        bool sel=(nav_idx==sel_node_idx);
        nav_idx++;
        auto lines=render_node(&node,sel,false,term_cols);
        for(auto& l:lines) dlines.push_back(l);
    }
}

// Count navigable items
int count_nav(Node& node) {
    int count=1; // this node's opening
    if((node.val->type==JType::Object||node.val->type==JType::Array)&&node.expanded) {
        for(auto& c:node.children) count+=count_nav(c);
    }
    return count;
}

// App state
struct App {
    Node root; int sel=0; int scroll=0; bool fullscreen; bool running=true; bool last_g=false;
    int prev_lines=0; int prev_width=0; int nav_count=1;

    App(JPtr json, bool fs): root(build(json,"",0,true)), fullscreen(fs) {
        root.is_last=true; nav_count=count_nav(root);
    }

    void update_nav_count() { nav_count=count_nav(root); }

    void clamp_sel() {
        if(sel<0) sel=0;
        if(sel>=nav_count) sel=nav_count-1;
    }

    int viewport_height() {
        if(fullscreen) return ROWS;
        // Count total display lines
        return ROWS; // will be determined at render time
    }

    void move_sel(int d) { sel+=d; clamp_sel(); }

    // Toggle expand/collapse of selected node
    Node* find_nav_node(Node& node, int& idx, int target) {
        if(idx==target) return &node;
        if((node.val->type==JType::Object||node.val->type==JType::Array)&&node.expanded) {
            idx++;
            for(auto& c:node.children) {
                Node* found=find_nav_node(const_cast<Node&>(c),idx,target);
                if(found) return found;
            }
            return nullptr;
        }
        idx++;
        return nullptr;
    }

    Node* get_sel_node() {
        int idx=0;
        return find_nav_node(root,idx,sel);
    }

    void toggle() {
        Node* n=get_sel_node();
        if(!n) return;
        if(n->val->type!=JType::Object&&n->val->type!=JType::Array) return;
        n->expanded=!n->expanded;
        update_nav_count(); clamp_sel();
    }

    void deep_expand(Node& n) {
        if(n.val->type==JType::Object||n.val->type==JType::Array){n.expanded=true;for(auto&c:n.children)deep_expand(c);}
    }
    void deep_collapse(Node& n) {
        if(n.val->type==JType::Object||n.val->type==JType::Array){n.expanded=false;for(auto&c:n.children)deep_collapse(c);}
    }
    void do_expand() { Node* n=get_sel_node(); if(n)deep_expand(*n); update_nav_count(); clamp_sel(); }
    void do_collapse() { Node* n=get_sel_node(); if(n)deep_collapse(*n); update_nav_count(); clamp_sel(); }
};

// Write to stdout
void write_all(const std::string& s) {
    if(s.empty()) return;
    const char* p=s.data(); size_t left=s.size();
    while(left>0){ssize_t n=write(STDOUT_FILENO,p,left);if(n<=0)break;p+=n;left-=n;}
}

// Render full frame
// Returns actual number of screen lines drawn
std::pair<int,int> do_render(App& app) {
    get_term_size();

    // Collect ALL display lines
    std::vector<DLine> all_dlines;
    int nav_idx=0;
    collect_dlines(app.root, all_dlines, app.sel, nav_idx, COLS);

    // Adjust scroll
    // Find the display line index of the selected item
    int sel_display_idx=-1;
    int nav_count=0;
    for(int i=0;i<(int)all_dlines.size();i++) {
        if(all_dlines[i].navigable) {
            if(nav_count==app.sel) { sel_display_idx=i; break; }
            nav_count++;
        }
    }

    int total_dlines=(int)all_dlines.size();
    int viewport;
    if(app.fullscreen) viewport=ROWS;
    else viewport=std::min(total_dlines, ROWS);

    // Adjust scroll to show sel_display_idx
    if(sel_display_idx>=0) {
        if(sel_display_idx<app.scroll) app.scroll=sel_display_idx;
        else if(sel_display_idx>=app.scroll+viewport) app.scroll=sel_display_idx-viewport+1;
    }
    if(app.scroll<0) app.scroll=0;
    int max_scroll=total_dlines-viewport;
    if(max_scroll<0) max_scroll=0;
    if(app.scroll>max_scroll) app.scroll=max_scroll;

    // Get visible slice
    int start=app.scroll;
    int end2=std::min(start+viewport, total_dlines);

    // Compute frame width
    int fw=0;
    for(int i=start;i<end2;i++) if(all_dlines[i].vwidth>fw) fw=all_dlines[i].vwidth;
    if(app.fullscreen) fw=COLS;
    else fw=std::min(fw,COLS);

    // Build output
    std::string out;
    // First line: CR (already at col 0 from positioning)
    // Actually: the initial render starts with \r\x1b[2K
    // For re-renders: just start writing (we're at col 0)
    // Let me use the same approach as original: first line has \r then content, no [2K]
    // (padding handles old content)

    bool first=true;
    int nlines=0;
    for(int i=start;i<end2;i++) {
        if(!first) out+="\r\n";
        first=false;
        out+=all_dlines[i].content;
        int pad=fw-all_dlines[i].vwidth;
        if(pad>0) out+=std::string(pad,' ');
        nlines++;
    }
    // Fill blank lines for fullscreen
    if(app.fullscreen) {
        while(nlines<viewport) {
            if(!first) out+="\r\n";
            first=false;
            out+=std::string(fw,' ');
            nlines++;
        }
    }

    write_all(out);
    return {nlines, fw};
}

enum class Key { None,Up,Down,Left,Right,Enter,Esc,LittleG,BigG,Plus,Minus,PageUp,PageDown,Other };

Key read_key() {
    unsigned char c; if(read(STDIN_FILENO,&c,1)<=0) return Key::None;
    if(c==27) {
        fd_set f; FD_ZERO(&f); FD_SET(STDIN_FILENO,&f); struct timeval tv={0,50000};
        if(select(STDIN_FILENO+1,&f,0,0,&tv)<=0) return Key::Esc;
        unsigned char n2; (void)read(STDIN_FILENO,&n2,1);
        if(n2=='[') {
            char seq[16]; int len=0;
            while(len<15) {
                FD_ZERO(&f); FD_SET(STDIN_FILENO,&f); tv={0,50000};
                if(select(STDIN_FILENO+1,&f,0,0,&tv)<=0) break;
                (void)read(STDIN_FILENO,(unsigned char*)&seq[len],1);
                if(seq[len]>='A'&&seq[len]<='Z'){len++;break;}
                if(seq[len]=='~'){len++;break;}
                len++;
            }
            seq[len]=0;
            if(len==1){if(seq[0]=='A')return Key::Up;if(seq[0]=='B')return Key::Down;if(seq[0]=='C')return Key::Right;if(seq[0]=='D')return Key::Left;}
            if(len>=2&&seq[len-1]=='~'){
                std::string code(seq,len-1);
                if(code=="5")return Key::PageUp; if(code=="6")return Key::PageDown;
            }
        } else if(n2=='O') {
            unsigned char s2; (void)read(STDIN_FILENO,&s2,1);
            if(s2=='A')return Key::Up;if(s2=='B')return Key::Down;if(s2=='C')return Key::Right;if(s2=='D')return Key::Left;
        }
        return Key::Esc;
    }
    switch(c) {
        case '\r': case '\n': return Key::Enter;
        case 'q': case 'Q': return Key::Esc;
        case 'j': return Key::Down; case 'k': return Key::Up;
        case 'h': return Key::Left; case 'l': return Key::Right;
        case '+': return Key::Plus; case '-': return Key::Minus;
        case 'g': return Key::LittleG; case 'G': return Key::BigG;
    }
    return Key::Other;
}

static volatile bool g_resize=false;
void sig_winch(int) { g_resize=true; }

// Full draw: position + CPR + render + back to top + hide cursor
void full_draw(App& app, bool first_draw=false) {
    std::string pos_seq;
    if(!first_draw) {
        // Go to bottom of previous display
        if(app.prev_lines>1){pos_seq+="\x1b[";pos_seq+=std::to_string(app.prev_lines-1);pos_seq+="B";}
        if(app.prev_width>0){pos_seq+="\x1b[";pos_seq+=std::to_string(app.prev_width);pos_seq+="C";}
        pos_seq+="\r";
        for(int i=0;i<app.prev_lines-1;i++) pos_seq+="\x1b[1A";
        pos_seq+="\x1b[6n";
    } else {
        // First draw: just CR + clear first line
        pos_seq+="\r\x1b[2K";
    }
    write_all(pos_seq);

    auto [nl,fw]=do_render(app);
    app.prev_lines=nl; app.prev_width=fw;

    // Back to top
    std::string back;
    if(nl>1){back+="\x1b[";back+=std::to_string(nl-1);back+="A";}
    if(fw>0){back+="\x1b[";back+=std::to_string(fw);back+="D";}
    back+="\x1b[?25l"; back+='\x00';
    write_all(back);
}

void run(App& app) {
    struct sigaction sa; sa.sa_handler=sig_winch;
    sigemptyset(&sa.sa_mask); sa.sa_flags=SA_RESTART;
    sigaction(SIGWINCH,&sa,nullptr);

    full_draw(app, true);

    while(app.running) {
        if(g_resize) {
            g_resize=false; get_term_size();
            // On resize: same as navigation (position + CPR + redraw)
            std::string pos;
            if(app.prev_lines>1){pos+="\x1b[";pos+=std::to_string(app.prev_lines-1);pos+="B";}
            if(app.prev_width>0){pos+="\x1b[";pos+=std::to_string(app.prev_width);pos+="C";}
            pos+="\r";
            for(int i=0;i<app.prev_lines-1;i++) pos+="\x1b[1A";
            pos+="\x1b[6n";
            write_all(pos);
            auto [nl,fw]=do_render(app);
            app.prev_lines=nl; app.prev_width=fw;
            std::string back;
            if(nl>1){back+="\x1b[";back+=std::to_string(nl-1);back+="A";}
            if(fw>0){back+="\x1b[";back+=std::to_string(fw);back+="D";}
            back+="\x1b[?25l"; back+='\x00';
            write_all(back);
            continue;
        }

        fd_set fds; FD_ZERO(&fds); FD_SET(STDIN_FILENO,&fds);
        struct timeval tv={0,100000};
        if(select(STDIN_FILENO+1,&fds,0,0,&tv)<=0) continue;

        Key k=read_key(); bool need=false;

        switch(k) {
            case Key::Esc: app.running=false; break;
            case Key::Up: app.move_sel(-1); app.last_g=false; need=true; break;
            case Key::Down: app.move_sel(1); app.last_g=false; need=true; break;
            case Key::Left: case Key::Right: app.last_g=false; break;
            case Key::Enter: app.toggle(); app.last_g=false; need=true; break;
            case Key::Plus: app.do_expand(); app.last_g=false; need=true; break;
            case Key::Minus: app.do_collapse(); app.last_g=false; need=true; break;
            case Key::BigG: app.sel=app.nav_count-1; app.last_g=false; need=true; break;
            case Key::LittleG:
                if(app.last_g){app.sel=0;app.last_g=false;need=true;}
                else app.last_g=true;
                break;
            case Key::PageUp: {int j=std::max(1,app.prev_lines-1);app.move_sel(-j);app.last_g=false;need=true;break;}
            case Key::PageDown: {int j=std::max(1,app.prev_lines-1);app.move_sel(j);app.last_g=false;need=true;break;}
            default: app.last_g=false; break;
        }

        if(need) full_draw(app, false);
    }
}

