int main(int argc, char** argv) {
    bool fullscreen=false, help=false, version=false, keybind=false, endflags=false;
    std::string filename;
    for(int i=1;i<argc;i++) {
        std::string a=argv[i];
        if(!endflags&&a=="--"){endflags=true;continue;}
        if(!endflags&&!a.empty()&&a[0]=='-') {
            if(a=="-h"||a=="--help") help=true;
            else if(a=="-v"||a=="--version") version=true;
            else if(a=="-f"||a=="--fullscreen") fullscreen=true;
            else if(a=="-k"||a=="--key"||a=="--keybinding") keybind=true;
            else help=true;
            continue;
        }
        filename=a;
    }
    if(version){std::cout<<"1.4.1\n";return 0;}
    if(help){print_help(argv[0]);print_help(argv[0]);return 0;}
    if(keybind){print_keys();return 0;}

    std::string json_str;
    if(filename.empty()) {
        if(!isatty(STDIN_FILENO)) {
            int tfd=open("/dev/tty",O_WRONLY);
            if(tfd>=0){(void)write(tfd,"Reading from stdin... ",22);close(tfd);}
        }
        std::string line;
