            else { out+=BOLD; out+=ct; out+=BOLD_OFF; }
            int vis=kpfx_len+(int)ct.size();
            res.push_back({out,vis,true});
        } else {
            // Expanded: key_prefix + ATTR + "{" + ATTR_OFF + [table_hint]
            std::string table_hint=""; int table_hint_len=0;
