            if(selected) { out+=REVERSE; out+=ob; out+=REV_OFF; out+=FG_DEF+BG_DEF; }
            else { out+=BOLD; out+=ob; out+=BOLD_OFF; }
            out+=table_hint;
            int vis=kpfx_len+1+table_hint_len;
            res.push_back({out,vis,true});
