int main(int argc, char** argv) {
    bool fullscreen=false, help=false, version=false, keybind=false, endflags=false;
    std::string filename;
    for(int i=1;i<argc;i++) {
        std::string a=argv[i];
        if(!endflags&&a=="--"){endflags=true;continue;}
        if(!endflags&&!a.empty()&&a[0]=='-') {
            if(a=="-h"||a=="--help") help=true;
            else if(a=="-v"||a=="--version") version=true;
            else if(a=="-f"||a=="--fullscreen") fullscreen=true;
            else if(a=="-k"||a=="--key"||a=="--keybinding") keybind=true;
            else help=true;
            continue;
        }
        filename=a;
    }
    if(version){std::cout<<"1.4.1\n";return 0;}
    if(help){print_help(argv[0]);print_help(argv[0]);return 0;}
    if(keybind){print_keys();return 0;}

    std::string json_str;
    if(filename.empty()) {
        if(!isatty(STDIN_FILENO)) {
            int tfd=open("/dev/tty",O_WRONLY);
            if(tfd>=0){(void)write(tfd,"Reading from stdin... ",22);close(tfd);}
        }
        std::string line;
        while(std::getline(std::cin,line)) json_str+=line+"\n";
    } else {
        std::ifstream f(filename);
        if(!f){std::cerr<<"Cannot open: "<<filename<<"\n";return 1;}
        std::ostringstream ss; ss<<f.rdbuf(); json_str=ss.str();
    }

    JPtr json=JsonParser::parse(json_str);
    get_term_size();
    App app(json,fullscreen);
    enable_raw();

    std::string startup;
    startup+='\x00'; startup+="\x1bP$q q\x1b\\";
    if(fullscreen) startup+="\x1b[?1049h";
    startup+="\x1b[?7l"; startup+="\x1b[?1000h"; startup+="\x1b[?1003h"; startup+="\x1b[?1015h"; startup+="\x1b[?1006h";
    write_all(startup);

    run(app);

    // Cleanup: position + CPR + final frame + back to top + hide + go to bottom + cleanup
    std::string pos;
    if(app.prev_lines>1){pos+="\x1b[";pos+=std::to_string(app.prev_lines-1);pos+="B";}
    if(app.prev_width>0){pos+="\x1b[";pos+=std::to_string(app.prev_width);pos+="C";}
    pos+="\r";
    for(int i=0;i<app.prev_lines-1;i++) pos+="\x1b[1A";
    pos+="\x1b[6n";
    write_all(pos);

    auto [fl,fw]=do_render(app);
    app.prev_lines=fl; app.prev_width=fw;

    std::string back;
    if(fl>1){back+="\x1b[";back+=std::to_string(fl-1);back+="A";}
    if(fw>0){back+="\x1b[";back+=std::to_string(fw);back+="D";}
    back+="\x1b[?25l"; write_all(back);

    std::string end_seq;
    if(fl>1){end_seq+="\x1b[";end_seq+=std::to_string(fl-1);end_seq+="B";}
    if(fw>0){end_seq+="\x1b[";end_seq+=std::to_string(fw);end_seq+="C";}
    if(fullscreen) end_seq+="\x1b[?1049l";
    end_seq+="\x1b[?1006l"; end_seq+="\x1b[?1015l"; end_seq+="\x1b[?1003l"; end_seq+="\x1b[?1000l";
    end_seq+="\x1b[?7h"; end_seq+="\x1b[?25h"; end_seq+="\x1b[1 q";
    end_seq+='\x00'; end_seq+="\r\r\n";
    write_all(end_seq);

    disable_raw();
    return 0;
}
