new_func = '''// Full draw: position + CPR + render + back to top + hide cursor
void full_draw(App& app, bool first_draw=false) {
    // First, compute new render
    get_term_size();

    if(!first_draw) {
        // We need to figure out if content shrinks
        // Compute new display size first
        std::vector<DLine> new_dlines;
        int nav_idx=0;
        collect_dlines(app.root, new_dlines, app.sel, nav_idx, COLS);
        int total_new=(int)new_dlines.size();
        int new_vp;
        if(app.fullscreen) new_vp=ROWS;
